// Content workload — Octane variant.
//
// Mirrors core/workloads/content.mjs (Vue) and content-react.mjs
// operation-for-operation: feed header + N keyed cards over the same class
// structure and the same bindings, so all three framework families sit on one
// FCP ladder. Element accounting is identical (4 chrome + 8 per card).
import fs from 'node:fs';
import path from 'node:path';

export function generateOctaneContentApp(octaneSrcDir, nCards = 125) {
  const app = `/** @jsxImportSource @octanejs/lynx/intrinsics */
// GENERATED by core/workloads/content-octane.mjs — do not edit by hand.
const CLS = ['card variant-0', 'card variant-1', 'card variant-2'];
const TITLES = ['Card title 0', 'Card title 1', 'Card title 2', 'Card title 3', 'Card title 4'];
const METAS = ['meta-0', 'meta-1', 'meta-2', 'meta-3', 'meta-4'];
const N = ${nCards};
const cards = Array.from({ length: N }, (_, i) => i);

export function ContentApp() @{
	<view class="feed">
		<view class="feed-header">
			<text class="feed-title">{'Today'}</text>
		</view>
		<view class="feed-list">
			@for (const i of cards; key i) {
				<view class={CLS[i % 3]!}>
					<image class="card-icon" src="asset://c.png" />
					<view class="card-body">
						<text class="card-title">{TITLES[i % 5]!}</text>
						<text class="card-desc">{'Static description text for the card body'}</text>
					</view>
					<view class="card-footer">
						<text class="card-meta">{METAS[i % 5]!}</text>
						<text class="card-cta">{'Open'}</text>
					</view>
				</view>
			}
		</view>
	</view>
}
`;
  const index = `// GENERATED by core/workloads/content-octane.mjs — do not edit by hand.
import { root } from '@octanejs/lynx';

import { ContentApp } from './ContentApp.lynx.tsrx';
import './app.css';

void root.render(ContentApp);
`;
  // Same declarations as the `<style scoped>` block in content.mjs — Octane has
  // no SFC, so the workload carries the stylesheet itself rather than borrowing
  // an app's.
  const css = `/* GENERATED by core/workloads/content-octane.mjs — matches content.mjs */
.feed { flex: 1; display: flex; flex-direction: column; background-color: #f5f5f5; }
.feed-header { padding: 12px 16px; }
.feed-title { font-size: 18px; font-weight: bold; color: #111; }
.feed-list { display: flex; flex-direction: column; }
.card { display: flex; flex-direction: row; margin: 4px 12px; padding: 8px; background-color: #fff; border-radius: 8px; }
.variant-0 { border-left-width: 2px; border-left-color: #42b883; }
.variant-1 { border-left-width: 2px; border-left-color: #35495e; }
.variant-2 { border-left-width: 2px; border-left-color: #ff7043; }
.card-icon { width: 32px; height: 32px; }
.card-body { flex: 1; display: flex; flex-direction: column; margin: 0 8px; }
.card-title { font-size: 14px; color: #222; }
.card-desc { font-size: 11px; color: #888; }
.card-footer { display: flex; flex-direction: column; align-items: flex-end; }
.card-meta { font-size: 10px; color: #aaa; }
.card-cta { font-size: 12px; color: #42b883; }
`;

  fs.mkdirSync(octaneSrcDir, { recursive: true });
  fs.writeFileSync(path.join(octaneSrcDir, 'ContentApp.lynx.tsrx'), app);
  fs.writeFileSync(path.join(octaneSrcDir, 'index-content.ts'), index);
  fs.writeFileSync(path.join(octaneSrcDir, 'app.css'), css);
  return { nCards, elements: 4 + nCards * 8 };
}
